//! interop_test — the Pointcheval-Sanders core and the threshold aggregation
//! checked against a FOREIGN implementation (`coconut-crypto` 0.14, arkworks),
//! whose outputs are recorded in `interop_vectors.zig` (generated by
//! `tools/vectors`; see the header there for the point/scalar encodings).
//!
//! EXTERNAL here: `psVerifyPlain` accepting foreign-issued credentials,
//! `aggregateCredential` reproducing the foreign aggregated sigma from foreign
//! partials, `aggregateVerificationKeys` reproducing the foreign group key.
//! Still SELF: the show-proof NIZK (implementation-defined transcript; the
//! last test only shows it runs over foreign-issued material).
//! `h` is taken from the foreign side as given (it is not `params.commonBase`).

const std = @import("std");
const bls = @import("bls12_381");
const keys = @import("keys.zig");
const cred = @import("credential.zig");
const params_mod = @import("params.zig");
const vectors = @import("interop_vectors.zig");

const g1 = bls.g1;
const g2 = bls.g2;
const Fr = bls.Fr;
const allocator = std.testing.allocator;

fn dec(comptime n: usize, hex: []const u8) [n]u8 {
    var out: [n]u8 = undefined;
    const r = std.fmt.hexToBytes(&out, hex) catch unreachable;
    std.debug.assert(r.len == n);
    return out;
}

fn pg1(hex: []const u8) !g1.Affine {
    return g1.fromBytesCompressed(dec(48, hex));
}

fn pg2(hex: []const u8) !g2.Affine {
    return g2.fromBytesCompressed(dec(96, hex));
}

fn scalar(hex: []const u8) !Fr {
    return Fr.fromBytes(dec(32, hex));
}

fn g1eql(a: g1.Affine, b: g1.Affine) bool {
    return std.mem.eql(u8, &g1.toBytesCompressed(a), &g1.toBytesCompressed(b));
}

fn g2eql(a: g2.Affine, b: g2.Affine) bool {
    return std.mem.eql(u8, &g2.toBytesCompressed(a), &g2.toBytesCompressed(b));
}

fn loadVk(c: vectors.Case) !keys.VerificationKey {
    const betas = try allocator.alloc(g2.Affine, c.q);
    errdefer allocator.free(betas);
    for (betas, c.vk_betas) |*b, hx| b.* = try pg2(hx);
    return .{ .alpha = try pg2(c.vk_alpha), .betas = betas };
}

fn loadAttrs(c: vectors.Case) ![]Fr {
    const a = try allocator.alloc(Fr, c.q);
    errdefer allocator.free(a);
    for (a, c.attributes) |*m, hx| m.* = try scalar(hx);
    return a;
}

fn partialsFor(c: vectors.Case, indices: []const u64, out: []cred.PartialCredential) !void {
    const h = try pg1(c.h);
    for (indices, out) |ix, *p| {
        p.* = .{ .index = ix, .h = h, .s = try pg1(c.partials[ix - 1].s) };
    }
}

test "foreign aggregated credentials verify under the foreign group key" {
    for (vectors.cases) |c| {
        const vk = try loadVk(c);
        defer vk.deinit(allocator);
        const attrs = try loadAttrs(c);
        defer allocator.free(attrs);
        const h = try pg1(c.h);
        for (c.subsets) |sub| {
            const sigma = cred.Credential{ .h = h, .s = try pg1(sub.sigma_s) };
            try std.testing.expect(cred.psVerifyPlain(vk, sigma, attrs));
            // Wire round trip of the foreign credential through our codec.
            const back = try cred.Credential.fromBytes(sigma.toBytes());
            try std.testing.expect(cred.psVerifyPlain(vk, back, attrs));
        }
    }
}

test "our aggregation of foreign partials equals the foreign aggregate" {
    for (vectors.cases) |c| {
        try std.testing.expect(c.subsets.len >= 2);
        const h = try pg1(c.h);
        for (c.subsets) |sub| {
            var partials: [8]cred.PartialCredential = undefined;
            try partialsFor(c, sub.indices, partials[0..sub.indices.len]);
            const agg = try cred.aggregateCredential(allocator, partials[0..sub.indices.len], c.t);
            try std.testing.expect(g1eql(agg.h, h));
            try std.testing.expect(g1eql(agg.s, try pg1(sub.sigma_s)));
        }
    }
}

test "our vk aggregation of foreign vk shares equals the foreign group key" {
    for (vectors.cases) |c| {
        const vk = try loadVk(c);
        defer vk.deinit(allocator);
        // Every subset the vectors name, in order.
        for (c.subsets) |sub| {
            var shares: [8]keys.VerificationKeyShare = undefined;
            for (sub.indices, 0..) |ix, k| {
                const fs = c.vk_shares[ix - 1];
                const betas = try allocator.alloc(g2.Affine, c.q);
                for (betas, fs.betas) |*b, hx| b.* = try pg2(hx);
                shares[k] = .{ .index = fs.index, .alpha = try pg2(fs.alpha), .betas = betas };
            }
            defer for (shares[0..sub.indices.len]) |s| allocator.free(s.betas);
            const agg = try keys.aggregateVerificationKeys(allocator, shares[0..sub.indices.len]);
            defer agg.deinit(allocator);
            try std.testing.expect(g2eql(agg.alpha, vk.alpha));
            for (agg.betas, vk.betas) |a, b| try std.testing.expect(g2eql(a, b));
        }
    }
}

test "tamper controls reject" {
    for (vectors.cases) |c| {
        const vk = try loadVk(c);
        defer vk.deinit(allocator);
        const attrs = try loadAttrs(c);
        defer allocator.free(attrs);
        const h = try pg1(c.h);
        const good = cred.Credential{ .h = h, .s = try pg1(c.subsets[0].sigma_s) };
        try std.testing.expect(cred.psVerifyPlain(vk, good, attrs));

        // (1) one attribute flipped (each position in turn).
        for (0..c.q) |i| {
            const bad = try allocator.dupe(Fr, attrs);
            defer allocator.free(bad);
            bad[i] = bad[i].add(Fr.one);
            try std.testing.expect(!cred.psVerifyPlain(vk, good, bad));
        }

        // (2) a different sigma: a single authority's partial is not the group sigma.
        const other = cred.Credential{ .h = h, .s = try pg1(c.partials[0].s) };
        try std.testing.expect(!cred.psVerifyPlain(vk, other, attrs));

        // (3) the wrong verification key: another case's key (same q), or a
        // single authority's share key for the same q.
        const share_vk = keys.VerificationKey{
            .alpha = try pg2(c.vk_shares[0].alpha),
            .betas = try allocator.alloc(g2.Affine, c.q),
        };
        defer allocator.free(share_vk.betas);
        for (share_vk.betas, c.vk_shares[0].betas) |*b, hx| b.* = try pg2(hx);
        try std.testing.expect(!cred.psVerifyPlain(share_vk, good, attrs));
        for (vectors.cases) |d| {
            if (d.q != c.q or std.mem.eql(u8, d.vk_alpha, c.vk_alpha)) continue;
            const wrong = try loadVk(d);
            defer wrong.deinit(allocator);
            try std.testing.expect(!cred.psVerifyPlain(wrong, good, attrs));
        }
    }
}

test "our show proof (SELF NIZK) runs over a foreign-issued credential" {
    for (vectors.cases) |c| {
        const vk = try loadVk(c);
        defer vk.deinit(allocator);
        const attrs = try loadAttrs(c);
        defer allocator.free(attrs);
        const sigma = cred.Credential{ .h = try pg1(c.h), .s = try pg1(c.subsets[0].sigma_s) };
        const p = try params_mod.Parameters.generate(allocator, c.q);
        defer p.deinit(allocator);

        var prng = std.Random.DefaultPrng.init(0xC0C0_0001 + c.q);
        const disclosed = try allocator.alloc(bool, c.q);
        defer allocator.free(disclosed);
        for (disclosed, 0..) |*d, i| d.* = (i % 2 == 0);
        const proof = try cred.proveCredentialSeededForTest(allocator, prng.random(), p, vk, sigma, attrs, disclosed);
        defer proof.deinit(allocator);

        const revealed = try allocator.alloc(Fr, (c.q + 1) / 2);
        defer allocator.free(revealed);
        var k: usize = 0;
        for (disclosed, attrs) |d, m| {
            if (!d) continue;
            revealed[k] = m;
            k += 1;
        }
        try std.testing.expect(try cred.verifyCredential(allocator, p, vk, proof, revealed));

        // A wrong claimed disclosed value must fail.
        const bad = try allocator.dupe(Fr, revealed);
        defer allocator.free(bad);
        bad[0] = bad[0].add(Fr.one);
        try std.testing.expect(!(try cred.verifyCredential(allocator, p, vk, proof, bad)));
    }
}
